def rule_matches(rule, field, value):
    current = rule[field]
    if current is None or current == []:
        return True
    if isinstance(current, list):
        return value in current
    return current == value

def capture_delay(value):
    if value in ('1', '2'):
        return '<3'
    if value == '7':
        return '>5'
    return value

def fraud_band(pct):
    if pct < 7.2:
        return '<7.2%'
    if pct < 7.7:
        return '7.2%-7.7%'
    if pct <= 8.3:
        return '7.7%-8.3%'
    return '>8.3%'

def volume_band(volume):
    if volume < 100000:
        return '<100k'
    if volume < 1000000:
        return '100k-1m'
    if volume <= 5000000:
        return '1m-5m'
    return '>5m'

def fixed(value, places):
    return f'{value:.{places}f}'

answers = {}

with open('inputs/payments.csv', newline='', encoding='utf-8') as f:
    issuer_counts = collections.Counter()
    fraud_ip_counts = collections.Counter()
    martinis_volume = 0.0
    martinis_fraud_volume = 0.0
    belles_rows = []
    monthly = collections.defaultdict(lambda: [0.0, 0.0])
    for row in csv.DictReader(f):
        issuer_counts[row['issuing_country']] += 1
        if row['has_fraudulent_dispute'] == 'True':
            fraud_ip_counts[row['ip_country']] += 1
        amount = float(row['eur_amount'])
        if row['merchant'] == 'Martinis_Fine_Steakhouse':
            martinis_volume += amount
            if row['has_fraudulent_dispute'] == 'True':
                martinis_fraud_volume += amount
        if row['merchant'] == 'Belles_cookbook_store':
            date = datetime.date(2023, 1, 1) + datetime.timedelta(days=int(row['day_of_year']) - 1)
            monthly[(date.year, date.month)][0] += amount
            if row['has_fraudulent_dispute'] == 'True':
                monthly[(date.year, date.month)][1] += amount
            belles_rows.append((row, date))

answers['5'] = issuer_counts.most_common(1)[0][0]
answers['49'] = 'A. ' + fraud_ip_counts.most_common(1)[0][0]
answers['70'] = 'yes' if martinis_fraud_volume / martinis_volume > 0.083 else 'no'

def matching_rules(filters):
    return [rule for rule in fees if all(rule_matches(rule, key, value) for key, value in filters.items())]

for task_id, filters in (
    ('1273', {'card_scheme': 'GlobalCard', 'is_credit': True}),
    ('1305', {'card_scheme': 'GlobalCard', 'account_type': 'H', 'merchant_category_code': 5812}),
):
    rules = matching_rules(filters)
    average_fee = sum(rule['fixed_amount'] + rule['rate'] * 10 / 10000 for rule in rules) / len(rules)
    answers[task_id] = fixed(average_fee, 6)

answers['1464'] = ', '.join(
    str(rule['ID'])
    for rule in sorted(fees, key=lambda item: item['ID'])
    if rule_matches(rule, 'account_type', 'R') and rule_matches(rule, 'aci', 'B')
)

belles = merchants['Belles_cookbook_store']

def month_bands(year, month):
    volume, fraud_volume = monthly[(year, month)]
    return volume_band(volume), fraud_band(fraud_volume / volume * 100)

def transaction_rules(row, volume_level, fraud_level, aci=None):
    filters = {
        'card_scheme': row['card_scheme'],
        'account_type': belles['account_type'],
        'capture_delay': capture_delay(belles['capture_delay']),
        'monthly_fraud_level': fraud_level,
        'monthly_volume': volume_level,
        'merchant_category_code': belles['merchant_category_code'],
        'is_credit': row['is_credit'] == 'True',
        'aci': aci or row['aci'],
        'intracountry': row['issuing_country'] == row['acquirer_country'],
    }
    return matching_rules(filters)

volume_level, fraud_level = month_bands(2023, 1)
jan10_ids = {
    rule['ID']
    for row, date in belles_rows
    if date.month == 1 and date.day == 10
    for rule in transaction_rules(row, volume_level, fraud_level)
}
answers['1681'] = ', '.join(map(str, sorted(jan10_ids)))

volume_level, fraud_level = month_bands(2023, 3)
march_ids = {
    rule['ID']
    for row, date in belles_rows
    if date.month == 3
    for rule in transaction_rules(row, volume_level, fraud_level)
}
answers['1753'] = ', '.join(map(str, sorted(march_ids)))

rule_384 = next(rule for rule in fees if rule['ID'] == 384)
jan_rule_volume = sum(
    float(row['eur_amount'])
    for row, date in belles_rows
    if date.month == 1
    and row['card_scheme'] == rule_384['card_scheme']
    and (row['is_credit'] == 'True') == rule_384['is_credit']
    and row['aci'] in rule_384['aci']
)
answers['1871'] = fixed((rule_384['rate'] - 1) * jan_rule_volume / 10000, 14)

volume_level, fraud_level = month_bands(2023, 1)
fraud_rows = [row for row, date in belles_rows if date.month == 1 and row['has_fraudulent_dispute'] == 'True']
aci_totals = {}
for aci in 'ABCDEFG':
    total = 0.0
    complete = True
    for row in fraud_rows:
        rule_fees = [
            rule['fixed_amount'] + rule['rate'] * float(row['eur_amount']) / 10000
            for rule in transaction_rules(row, volume_level, fraud_level, aci)
        ]
        if not rule_fees:
            complete = False
            break
        total += min(rule_fees)
    if complete:
        aci_totals[aci] = total
preferred_aci = min(aci_totals, key=aci_totals.get)
answers['2697'] = f'{preferred_aci}:{fixed(aci_totals[preferred_aci], 2)}'

question_ids = [json.loads(line)['task_id'] for line in open('inputs/questions.jsonl', encoding='utf-8')]
with open('answers.jsonl', 'w', encoding='utf-8') as out:
    for task_id in question_ids:
        out.write(json.dumps({'task_id': task_id, 'answer': answers[task_id]}, ensure_ascii=False) + '\n')
